#include <iostream>
#include <set>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    set<string> distinct;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        distinct.insert(s);
        s = s.back() + s.substr(0, s.size() - 1);
    }

    cout << distinct.size() << '\n';
    return 0;
}

